/*
 * A070740  Order of the subgroup of the symmetric group S_(2n) generated by
 *          the 2 cycles: (1,2,...n,2n,2n-1,...,n+1) and (1,2,...,2n).
 * https://oeis.org/A070740
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (2n)! if n is even a(n) = (n!)^2 / 2 if n ≡ 1 (mod 4)
 *            a(n) = (n!)^2 if n ≡ 3 (mod 4) (Offset: a(2) is the first term)
 * Range:     u8 n <= 3, u16 n <= 5, u32 n <= 7, u64 n <= 11, u128 n <= 17,
 *            big any n
 * Helpers:   factorial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/factorial.h"

seq_t a(idx_t n)
{
    if (n < 2) return 0;           /* undefined for n < 2, handled silently */

    if ((n & 1) == 0)              /* even n */
    {
        /* (2n)! */
        /* use 2*n to avoid overflow of intermediate indices; 
           built‑in types handle small values safely. */
        return factorial(2 * n);
    }
    else if ((n & 3) == 1)        /* n ≡ 1 mod 4 */
    {
        seq_t f = factorial(n);
        return (f * f) / 2;
    }
    else                           /* n ≡ 3 mod 4 */
    {
        seq_t f = factorial(n);
        return f * f;
    }
}
